# Backward compatibility alias
NSE_FO_UNIVERSE: Dict[str, SymbolSpec] = NSE_EQUITY_UNIVERSE

def get_symbol_spec(symbol: str) -> SymbolSpec:
    clean_sym = symbol.upper().replace(".NS", "")
    if clean_sym in NSE_EQUITY_UNIVERSE:
        return NSE_EQUITY_UNIVERSE[clean_sym]
    return SymbolSpec(
        symbol=clean_sym,
        name=f"{clean_sym} Ltd",
        lot_size=1,
        strike_step=1.0,
        sector="Diversified",
        cap_category="MID_CAP",
        yf_ticker=f"{clean_sym}.NS"
    )

def get_universe_by_category(category: Literal["LARGE_CAP", "MID_CAP", "SMALL_CAP"]) -> List[str]:
    return [sym for sym, spec in NSE_EQUITY_UNIVERSE.items() if spec.cap_category == category]

def get_all_symbols() -> List[str]:
    return list(NSE_EQUITY_UNIVERSE.keys())
